#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <unordered_map>
#include <vector>
#include "ecc2k130/include/curveparams.h"
#include "ecc2k130/include/walk.h"
using C=CfgF23;using R=Ref<C>;using E=R::Elem;using P=R::Point;
struct K{unsigned long long v[3];bool operator==(K const&o)const{return v[0]==o.v[0]&&v[1]==o.v[1]&&v[2]==o.v[2];}};struct H{size_t operator()(K const&k)const{return size_t(k.v[0]*0x9e3779b97f4a7c15ULL^k.v[1]*0xbf58476d1ce4e5b9ULL^k.v[2]*0x94d049bb133111ebULL);}};static K key(E x){x=R::canonical(x);return K{{x.v[0],x.v[1],x.v[2]}};}
struct W{P p;U192 a,b;unsigned long long it=0;};struct S{std::vector<unsigned long long>totals,walks;unsigned solved=0,bad=0,overdue=0,invariantBad=0;unsigned long long zeroDen=0,bridges3=0,bridges1=0;};
static void show(const char*l,std::vector<unsigned long long>v){std::sort(v.begin(),v.end());long double s=0;for(auto x:v)s+=x;std::printf("%s_mean=%.6Lf %s_median=%llu %s_p90=%llu",l,s/v.size(),l,v[v.size()/2],l,v[v.size()*9/10]);}
int main(int argc,char**argv){unsigned trials=argc>1?unsigned(std::strtoul(argv[1],nullptr,10)):100;int first=argc>2?std::atoi(argv[2]):0,last=argc>2?first+1:2;U192 ell=u192_from_dec(eccF23::ELL_DEC),s=u192_from_dec(eccF23::S_DEC),sp[256];sp[0]=u192_from(1);for(int i=1;i<256;i++)sp[i]=mod_mul(sp[i-1],s,ell);P B=R::make(R::fromLimbs(eccF23::PX),R::fromLimbs(eccF23::PY)),Q=R::make(R::fromLimbs(eccF23::QX),R::fromLimbs(eccF23::QY));U192 bridge1=mod_add(u192_from(1),sp[1],ell),bridge3=mod_add(u192_from(1),sp[3],ell);
 for(int mode=first;mode<last;mode++){S z;for(unsigned trial=0;trial<trials;trial++){std::unordered_map<K,W,H>tab;unsigned long long total=0;for(unsigned wi=0;wi<20000;wi++){W w;w.p=R::startPoint(eccSeedFor(40000+trial,wi),B,Q,&w.a,ell,sp);w.b=u192_from(1);for(;;w.it++){if(w.it>=1024){z.overdue++;w.p.inf=true;break;}int hw=R::weight(w.p.x);if(hw<=eccF23::DP_WEIGHT)break;if(!mode){int j=R::jOf(hw);U192 f=mod_add(u192_from(1),sp[j],ell);w.a=mod_mul(w.a,f,ell);w.b=mod_mul(w.b,f,ell);w.p=R::addPt(w.p,R::frob(w.p,j));}else if(R::polySelectBridge3(w.p.x)){w.a=mod_mul(w.a,bridge3,ell);w.b=mod_mul(w.b,bridge3,ell);w.p=R::addPt(w.p,R::frob(w.p,3));z.bridges3++;}else{w.a=mod_mul(w.a,bridge1,ell);w.b=mod_mul(w.b,bridge1,ell);w.p=R::addPt(w.p,R::frob(w.p,1));z.bridges1++;}if(w.p.inf){z.bad++;break;}}
 total+=w.it;if(w.p.inf)continue;K k=key(w.p.x);auto[at,fresh]=tab.emplace(k,w);if(fresh)continue;W const&a=w;W const&b=at->second;P sa=R::addPt(R::scalarMul(B,a.a),R::scalarMul(Q,a.b)),sb=R::addPt(R::scalarMul(B,b.a),R::scalarMul(Q,b.b));if(!R::eq(sa,a.p)||!R::eq(sb,b.p)){z.invariantBad++;continue;}bool ok=false;for(int rot=0;rot<C::M&&!ok;rot++){P q=R::frob(b.p,rot);int eps=R::eq(q,a.p)?1:(R::eq(R::neg(q),a.p)?-1:0);if(!eps)continue;U192 sc=sp[rot];if(eps<0)sc=mod_neg(sc,ell);U192 num=mod_sub(a.a,mod_mul(sc,b.a,ell),ell),den=mod_sub(mod_mul(sc,b.b,ell),a.b,ell);if(u192_is_zero(den)){z.zeroDen++;continue;}U192 x=mod_mul(num,mod_inv(den,ell),ell);ok=R::eq(R::scalarMul(B,x),Q);}if(ok){z.totals.push_back(total);z.walks.push_back(wi+1);z.solved++;break;}}}
 const char*name=mode?"poly12-sparse-bridge3":"selected";std::printf("mode=%s trials=%u solved=%u bad=%u invariant_bad=%u overdue=%u zero_den=%llu bridges1=%llu bridges3=%llu ",name,trials,z.solved,z.bad,z.invariantBad,z.overdue,z.zeroDen,z.bridges1,z.bridges3);show("iterations",z.totals);std::printf(" ");show("walks",z.walks);std::printf("\n");}}
